    c = Synchro.lookupOne(Synchro_Export=$Synchro_Export, Synchro_Table=$Synchro_Table, Synchro_Type="complet").Synchro_Lot or ""
    return "%d:%08x" % (len(c), zlib.crc32(c.encode()))
